'use strict';

// MODULES //

var logger = require( 'debug' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var replace = require( '@stdlib/string/base/replace' );
var Scale = require( '@stdlib/plot/vega/scale' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getBins = require( './bins/get.js' );
var setBins = require( './bins/set.js' );

var getClamp = require( './clamp/get.js' );
var setClamp = require( './clamp/set.js' );

var getPadding = require( './padding/get.js' );
var setPadding = require( './padding/set.js' );

var getNice = require( './nice/get.js' );
var setNice = require( './nice/set.js' );

var getType = require( './type/get.js' );
var setType = require( './type/set.js' );

var getZero = require( './zero/get.js' );
var setZero = require( './zero/set.js' );


// VARIABLES //

var debug = logger( 'vega:scale-quantitative:main' );


// FUNCTIONS //

/**
* Transforms an "assignment" error message to an "option validation" error message.
*
* @private
* @param {string} msg - error message
* @returns {string} transformed message
*/
function transformErrorMessage( msg ) {
	var m = replace( msg, /invalid assignment\. `([^ ]+)`/, 'invalid option. `$1` option' );
	return replace( m, /\. Value:/, '. Option:' );
}


// MAIN //

/**
* Quantitative scale constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.name - scale name
* @param {(Collection|Object|Signal)} [options.bins] - bin boundaries over the scale domain
* @param {boolean} [options.clamp=false] - boolean indicating whether to clamp output values to the scale range
* @param {(Collection|Object|Signal)} [options.domain] - domain of associated data values
* @param {number} [options.domainMax] - maximum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMin] - minimum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMid] - single mid-point value inserted into a two-element domain
* @param {Collection} [options.domainRaw] - array of raw domain values which overrides the `domain` property
* @param {(string|Object)} [options.interpolate] - scale range interpolation method
* @param {(boolean|number|Signal)} [options.nice=false] - scale domain "nicing"
* @param {number} [options.padding] - scale domain padding (in pixels)
* @param {(Collection|Object|Signal|string)} [options.range] - scale range
* @param {boolean} [options.reverse=false] - boolean indicating whether to reverse the order of the scale range
* @param {boolean} [options.round=false] - boolean indicating whether to round numeric output values to integers
* @param {string} [options.type='linear'] - scale type
* @param {boolean} [options.zero] - boolean indicating whether the scale domain should include zero
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {QuantitativeScale} scale instance
*
* @example
* var scale = new QuantitativeScale({
*     'name': 'xScale'
* });
* // returns <QuantitativeScale>
*/
function QuantitativeScale( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof QuantitativeScale ) ) {
		return new QuantitativeScale( options );
	}
	if ( !isPlainObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	Scale.call( this, options );

	// Resolve the default scale configuration:
	opts = defaults();

	// Set internal scale properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Check for required properties...
	if ( !hasProp( options, 'name' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify the scale name.' );
	}
	// Validate provided options by attempting to assign option values to corresponding scale fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from a parent prototype.
*/
inherit( QuantitativeScale, Scale );

/**
* Constructor name.
*
* @private
* @name name
* @memberof QuantitativeScale
* @readonly
* @type {string}
*/
setReadOnly( QuantitativeScale, 'name', 'QuantitativeScale' );

/**
* Bins boundaries of the scale domain.
*
* @name bins
* @memberof QuantitativeScale.prototype
* @type {(Array|Object|Signal|void)}
*
* @example
* var scale = new QuantitativeScale({
*     'name': 'xScale',
*     'bins': [ 0, 5, 10, 15, 20 ]
* });
*
* var v = scale.bins;
* // returns [ 0, 5, 10, 15, 20 ]
*/
setReadWriteAccessor( QuantitativeScale.prototype, 'bins', getBins, setBins );

/**
* Boolean indicating whether to clamp output values to the scale range.
*
* @name clamp
* @memberof QuantitativeScale.prototype
* @type {boolean}
* @default false
*
* @example
* var scale = new QuantitativeScale({
*     'name': 'xScale',
*     'clamp': true
* });
*
* var v = scale.clamp;
* // returns true
*/
setReadWriteAccessor( QuantitativeScale.prototype, 'clamp', getClamp, setClamp );

/**
* Scale domain padding (in pixels).
*
* @name padding
* @memberof QuantitativeScale.prototype
* @type {(number|void)}
*
* @example
* var scale = new QuantitativeScale({
*     'name': 'xScale',
*     'padding': 10
* });
*
* var v = scale.padding;
* // returns 10
*/
setReadWriteAccessor( QuantitativeScale.prototype, 'padding', getPadding, setPadding );

/**
* Scale domain "nicing".
*
* @name nice
* @memberof QuantitativeScale.prototype
* @type {(boolean|number|Signal)}
* @default false
*
* @example
* var scale = new QuantitativeScale({
*     'name': 'xScale',
*     'nice': true
* });
*
* var v = scale.nice;
* // returns true
*/
setReadWriteAccessor( QuantitativeScale.prototype, 'nice', getNice, setNice );

/**
* Scale type.
*
* @name type
* @memberof QuantitativeScale.prototype
* @type {string}
* @default 'linear'
*
* @example
* var scale = new QuantitativeScale({
*     'name': 'xScale',
*     'type': 'log'
* });
*
* var v = scale.type;
* // returns 'log'
*/
setReadWriteAccessor( QuantitativeScale.prototype, 'type', getType, setType );

/**
* Boolean indicating whether the scale domain should include zero.
*
* @name zero
* @memberof QuantitativeScale.prototype
* @type {(boolean|void)}
*
* @example
* var scale = new QuantitativeScale({
*     'name': 'xScale',
*     'zero': false
* });
*
* var v = scale.zero;
* // returns false
*/
setReadWriteAccessor( QuantitativeScale.prototype, 'zero', getZero, setZero );


// EXPORTS //

module.exports = QuantitativeScale;
